pragma solidity ^0.8.33;

import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";

contract Auction is IERC721Receiver {
    error AlreadyFinished();

    address public owner;
    NFT public auctionedToken;
    IERC20 public token;
    IERC721 public coll;
    uint256 public startTime;
    uint256 public endTime;

    struct NFT {
        uint256 tokenId;
    }

    constructor(
        IERC20 _token,
        IERC721 _collection,
        uint256 tokenId,
        address _owner,
        uint256 _startTime,
        uint256 _endTime
    ) {
        require(_collection.ownerOf(tokenId) == msg.sender && msg.sender == _owner && block.timestamp < _endTime);
        owner = _owner;
        token = _token;
        coll = _collection;
        startTime = _startTime;
        endTime = _endTime;
        auctionedToken = NFT({tokenId: tokenId});
        _collection.safeTransferFrom(_owner, address(this), tokenId);
    }

    mapping(address => uint256) public bids;
    mapping(address => bool) public hasBid;
    address public highestBidder;

    function bid(uint256 amount) public {
        if (block.timestamp > endTime) {
            revert AlreadyFinished();
        }
        if (highestBidder != address(0) && !hasBid[msg.sender] && amount <= bids[highestBidder]) {
            revert();
        }
        hasBid[msg.sender] = true;
        bids[msg.sender] += amount;
        token.transferFrom(msg.sender, address(this), amount);
        if (highestBidder == address(0) || bids[msg.sender] > bids[highestBidder]) {
            highestBidder = msg.sender;
        }
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }

    bool public finished;

    function finishAuction() public returns (address) {
        if (finished) {
            revert AlreadyFinished();
        }
        if (msg.sender != owner) {
            revert();
        }
        if (block.timestamp <= endTime) {
            revert();
        }
        finished = true;
        address winner = highestBidder;
        coll.safeTransferFrom(address(this), winner, auctionedToken.tokenId);
        return winner;
    }
}

content.thinking:
The `finishAuction` function uses `safeTransferFrom` to send the NFT to the winner. Since the winner (highest bidder) is an EOA, the callback will fail. Need to use plain `transferFrom` instead.

Also, looking at the test more carefully:

```solidity
function _test_executeFinish(address caller) internal {
    if (ghost_has_finished) {
        vm.expectRevert(Auction.AlreadyFinished.selector);
        auction.finishAuction();
        ...
    }
    address winner = auction.finishAuction();
```

This test calls `finishAuction` from any caller (including non-owner), yet the function reverts if `msg.sender != owner`. The test doesn't expect that revert — it expects either `AlreadyFinished` or a successful return. So the owner-only check is wrong per the spec.

Removing the owner-only check to match the test, which calls `_test_executeFinish(owner)` only after the loop but `_executeFinish(currentBidder)` with arbitrary bidders during the loop.

Also need to swap `safeTransferFrom` for `transferFrom` since the winner is an EOA and won't accept the callback.

